import java.util.*;
import java.io.*;

public class Main {
    static char[][] mapA = new char[12][12], mapB = new char[12][12];
    static int sizeN, maxT;
    static boolean[][][][][] visitedStates = new boolean[70][12][12][12][12];
    static boolean[][][][] canReach = new boolean[12][12][12][12];
    static int[][] timeGrid = new int[12][12];

    static void runDP(int step, int x, int y, int xRef, int yRef) {
        if (maxT >= 70 || x < 0 || x >= sizeN || y < 0 || y >= sizeN)
            return;
        if (mapA[x][y] < '0' || mapA[x][y] > '9')
            return;
        if (step > maxT + 1)
            return;
        if (visitedStates[step][x][y][xRef][yRef])
            return;
        if (timeGrid[x][y] != 0 && step > timeGrid[x][y])
            return;
        if (timeGrid[x][y] == step && (mapB[x][y] > '9' || mapB[x][y] <= '0'))
            return;
        visitedStates[step][x][y][xRef][yRef] = true;

        if (step < timeGrid[x][y]) {
            runDP(step + 1, x, y, xRef, yRef);
            runDP(step + 1, x + 1, y, xRef, yRef);
            runDP(step + 1, x - 1, y, xRef, yRef);
            runDP(step + 1, x, y + 1, xRef, yRef);
            runDP(step + 1, x, y - 1, xRef, yRef);
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int t = Integer.parseInt(st.nextToken());
        sizeN = n;
        maxT = t;

        for (int i = 0; i < n; i++) {
            String line = br.readLine();
            for (int j = 0; j < n; j++) {
                mapA[i][j] = line.charAt(j);
            }
        }
        for (int i = 0; i < n; i++) {
            String line = br.readLine();
            for (int j = 0; j < n; j++) {
                mapB[i][j] = line.charAt(j);
            }
        }

        int[][][] graph = new int[210][]; // Using List for dynamic sizing
        List<List<Integer>> graphList = new ArrayList<>();
        for (int i = 0; i < 210; i++) {
            graphList.add(new ArrayList<>());
        }
        int[] E = new int[210];
        int[] H = new int[210];
        int[][] C = new int[210][210];
        int[][] pN = new int[11][11];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                timeGrid[i][j] = -1;
            }
        }

        Queue<int[]> q = new LinkedList<>();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (mapA[i][j] == 'Z') {
                    timeGrid[i][j] = 0;
                    q.offer(new int[]{i, j});
                }
            }
        }

        int[] di = {-1, 0, 1, 0};
        int[] dj = {0, -1, 0, 1};

        while (!q.isEmpty()) {
            int[] p = q.poll();
            int pi = p[0], pj = p[1];
            if (timeGrid[pi][pj] >= t) continue;
            for (int d = 0; d < 4; d++) {
                int ni = pi + di[d], nj = pj + dj[d];
                if (ni >= 0 && ni < n && nj >= 0 && nj < n && mapA[ni][nj] >= '0' && mapA[ni][nj] <= '9' && timeGrid[ni][nj] == -1) {
                    timeGrid[ni][nj] = timeGrid[pi][pj] + 1;
                    q.offer(new int[]{ni, nj});
                }
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (timeGrid[i][j] == -1)
                    timeGrid[i][j] = t;
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (mapA[i][j] >= '0' && mapA[i][j] <= '9') {
                    runDP(0, i, j, i, j);
                }
            }
        }

        List<Integer> startNodes = new ArrayList<>();
        graphList.set(0, startNodes);
        int graphSize = 1;

        for (int i1 = 0; i1 < n; i1++) {
            for (int j1 = 0; j1 < n; j1++) {
                for (int i2 = 0; i2 < n; i2++) {
                    for (int j2 = 0; j2 < n; j2++) {
                        for (int nt = 0; nt <= t; nt++) {
                            canReach[i1][j1][i2][j2] |= visitedStates[nt][i1][j1][i2][j2];
                        }
                    }
                }
            }
        }

        for (int i1 = 0; i1 < n; i1++) {
            for (int j1 = 0; j1 < n; j1++) {
                if (mapA[i1][j1] > '0' && mapA[i1][j1] <= '9') {
                    int k = graphSize;
                    List<Integer> g = new ArrayList<>();
                    graphList.add(g);
                    E[k] = mapA[i1][j1] - '0';

                    for (int i2 = 0; i2 < n; i2++) {
                        for (int j2 = 0; j2 < n; j2++) {
                            if (mapB[i2][j2] > '0' && mapB[i2][j2] <= '9') {
                                if (canReach[i2][j2][i1][j1]) {
                                    int _k;
                                    if (pN[i2][j2] == 0) {
                                        List<Integer> _g = new ArrayList<>();
                                        _k = graphList.size();
                                        graphList.add(_g);
                                        pN[i2][j2] = _k;
                                    } else {
                                        _k = pN[i2][j2];
                                    }
                                    graphList.get(k).add(_k);
                                    graphList.get(_k).add(k);
                                    C[k][_k] = 10000;
                                    C[_k][k] = 0;
                                }
                            }
                        }
                    }
                    graphSize++;
                }
            }
        }

        for (int i2 = 0; i2 < n; i2++) {
            for (int j2 = 0; j2 < n; j2++) {
                if (mapB[i2][j2] > '0' && mapB[i2][j2] <= '9' && pN[i2][j2] > 0) {
                    int _k = pN[i2][j2];
                    graphList.get(_k).add(0);
                    C[_k][0] = mapB[i2][j2] - '0';
                    C[0][_k] = 0;
                }
            }
        }

        int[] F = new int[graphList.size()];
        Arrays.fill(F, 0);
        int[] HArr = new int[graphList.size()];
        Arrays.fill(HArr, 0);
        int[] EArr = E;
        boolean allDone;

        do {
            allDone = true;
            for (int i = 1; i < graphList.size(); i++) {
                while (EArr[i] > 0) {
                    boolean movedFlag = true;
                    int minH = Integer.MAX_VALUE;
                    for (int neighbor : graphList.get(i)) {
                        if (C[i][neighbor] - EArr[i] > 0 && HArr[i] == HArr[neighbor] + 1) {
                            int deltaFlow = Math.min(C[i][neighbor] - EArr[i], EArr[i]);
                            F[i] += deltaFlow;
                            F[neighbor] -= deltaFlow;
                            EArr[i] -= deltaFlow;
                            EArr[neighbor] += deltaFlow;
                            movedFlag = false;
                            allDone = false;
                            if (EArr[i] == 0) break;
                        }
                        minH = Math.min(minH, HArr[neighbor]);
                    }
                    if (HArr[i] != minH + 1 && minH != Integer.MAX_VALUE)
                        HArr[i] = minH + 1;
                    if (movedFlag) break;
                }
            }
        } while (!allDone);

        System.out.println(EArr[0]);
    }
}
